def forward(apps, schema_editor):
    ConfigTemplate = apps.get_model("inventory", "ConfigTemplate")
    for t in ConfigTemplate.objects.all():
        if OLD_FW in t.body:
            t.body = t.body.replace(OLD_FW, NEW_FW)
            t.save(update_fields=["body"])
        elif t.role in DESCRIPTIONS and t.role != "igw" and NEW_FW not in t.body:
            print(f"  inventory 0063: {t.role} not changed (its management block was edited by hand)")
    for role, desc in DESCRIPTIONS.items():
        ConfigTemplate.objects.filter(role=role).update(description=desc)


